package com.fakelegacy.order.service;

import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import com.fakelegacy.order.domain.Order;
import com.fakelegacy.order.domain.OrderLine;
import com.fakelegacy.order.domain.ProductCache;
import com.fakelegacy.order.repo.ReturnRecordRepository;
import com.fakelegacy.order.web.ApiRequests.ReturnItem;

@Service
public class ReturnService {

    private static final int MAX_RETURNS_PER_90_DAYS = 3;

    @Autowired
    private ProductCacheService productCache;

    @Autowired
    private ReturnRecordRepository returnRecords;

    /** Checks the returned items and the customer's return history; yields sku -> qty. */
    public Map<String, Integer> validate(Order order, List<ReturnItem> items) {
        if (items == null || items.isEmpty()) {
            throw new IllegalStateException("items must be a non-empty list of {sku, qty}");
        }
        Map<String, Integer> wanted = new LinkedHashMap<>();
        for (ReturnItem item : items) {
            if (item == null || item.sku() == null || item.qty() == null || item.qty() <= 0) {
                throw new IllegalStateException("each item needs a sku and a qty > 0");
            }
            wanted.merge(item.sku(), item.qty(), Integer::sum);
        }
        for (Map.Entry<String, Integer> e : wanted.entrySet()) {
            OrderLine line = order.findLine(e.getKey());
            if (line == null) {
                throw new IllegalStateException("sku " + e.getKey() + " is not part of order " + order.getId());
            }
            if (line.getReturnedQuantity() + e.getValue() > line.getQuantity()) {
                throw new IllegalStateException("cannot return more than purchased for " + e.getKey());
            }
            ProductCache pc = productCache.find(e.getKey());
            String category = pc != null ? pc.getCategory() : line.getCategory();
            if ("FOOD".equals(category)) {
                throw new IllegalStateException("food products cannot be returned: " + e.getKey());
            }
        }
        long recent = returnRecords.countSince(order.getCustomerId(), LocalDateTime.now().minusDays(90));
        if (recent >= MAX_RETURNS_PER_90_DAYS) {
            throw new IllegalStateException("too many returns in the last 90 days");
        }
        return wanted;
    }
}
